// One order shape for every channel, plus validation.
const cfg = $('Hub Settings').first().json;
const s = v => (v === undefined || v === null ? '' : String(v).trim());
const n = v => { const x = Number(v); return Number.isFinite(x) ? x : 0; };
let o;
if ($('Shopify Order').isExecuted) {
  const r = $('Shopify Order').first().json;
  o = { channel: 'Shopify', order_id: s(r.name || r.id), created_at: s(r.created_at), customer: [r.customer?.first_name, r.customer?.last_name].filter(Boolean).join(' ') || s(r.email),
    contact: s(r.email || r.phone), currency: s(r.currency), total: n(r.total_price),
    items: (r.line_items || []).map(l => ({ sku: s(l.sku), name: s(l.title), quantity: n(l.quantity), price: n(l.price) })) };
} else if ($('WooCommerce Order').isExecuted) {
  const r = $('WooCommerce Order').first().json;
  o = { channel: 'WooCommerce', order_id: s(r.number || r.id), created_at: s(r.date_created), customer: [r.billing?.first_name, r.billing?.last_name].filter(Boolean).join(' '),
    contact: s(r.billing?.email || r.billing?.phone), currency: s(r.currency), total: n(r.total),
    items: (r.line_items || []).map(l => ({ sku: s(l.sku), name: s(l.name), quantity: n(l.quantity), price: n(l.price) })) };
} else {
  const r = $('Marketplace Order').first().json.body ?? {};
  o = { channel: s(r.channel) || 'Marketplace', order_id: s(r.order_id), created_at: s(r.created_at), customer: s(r.customer_name),
    contact: s(r.customer_phone || r.customer_email), currency: s(r.currency), total: n(r.total),
    items: (Array.isArray(r.items) ? r.items : []).map(l => ({ sku: s(l.sku), name: s(l.name), quantity: n(l.quantity), price: n(l.price) })) };
}
o.currency = o.currency || cfg.currency;
o.created_at = o.created_at || DateTime.now().toISO();
o.order_key = o.channel.toLowerCase() + ':' + o.order_id;
const problems = [];
if (!o.order_id) problems.push('order_id is missing');
if (!o.items.length) problems.push('the order has no items');
o.items.forEach((l, i) => {
  if (!l.sku) problems.push('item ' + (i + 1) + ' (' + (l.name || 'no name') + ') has no SKU');
  if (!(l.quantity > 0)) problems.push('item ' + (i + 1) + ' has quantity ' + l.quantity);
});
return [{ json: { ...o, valid: problems.length === 0, problems } }];

// Current stock = Start Stock + all movements after Counted At.
const inv = {};
for (const i of $('Read Inventory').all()) if (i.json.SKU) inv[String(i.json.SKU).trim()] = i.json;
const moves = new Map();
for (const i of $('Get SKU Moves').all()) moves.set(i.json.id, i.json);
const thisOrder = {};
for (const i of $('One Item per Line').all()) thisOrder[i.json.line.sku] = (thisOrder[i.json.line.sku] || 0) + Number(i.json.line.quantity || 0);
return Object.entries(thisOrder).map(([sku, sold]) => {
  const item = inv[sku];
  const counted = item?.['Counted At'] ? DateTime.fromISO(String(item['Counted At'])) : null;
  const delta = [...moves.values()].filter(m => m.sku === sku && (!counted || !counted.isValid || DateTime.fromISO(String(m.created_at)) > counted))
    .reduce((s, m) => s + Number(m.qty || 0), 0);
  const start = Number(item?.['Start Stock'] || 0);
  const current = start + delta;
  const previous = current + sold;
  const threshold = Number(item?.['Low Stock At'] ?? 0);
  return { json: {
    sku, name: item?.Name || '', known: !!item, sold, current, previous, threshold,
    crossed_low: !!item && previous > threshold && current <= threshold,
    shopify_item_id: String(item?.['Shopify Inventory Item ID'] || ''),
    woo_product_id: String(item?.['WooCommerce Product ID'] || ''),
  } };
});

