// Today's sales per channel, best sellers and stock that needs attention.
const cur = $('Report Settings').first().json.currency;
const today = DateTime.now().startOf('day');
const orders = $('Read Orders').all().map(i => i.json).filter(o => o['Order Key'] && DateTime.fromISO(String(o.Date)).startOf('day').equals(today));
const revenue = orders.reduce((s, o) => s + (Number(o.Total) || 0), 0);
const byChannel = {};
for (const o of orders) { const c = (byChannel[o.Channel] ??= { orders: 0, revenue: 0 }); c.orders++; c.revenue += Number(o.Total) || 0; }
const units = {};
for (const o of orders) for (const part of String(o.Items || '').split('; ')) { const m = part.match(/^(\d+) × (\S+) ?(.*)$/); if (m) { units[m[2]] ??= { sku: m[2], name: m[3], qty: 0 }; units[m[2]].qty += Number(m[1]); } }
const best = Object.values(units).sort((a, b) => b.qty - a.qty).slice(0, 5);
const moves = $('Load Stock Moves').all().map(i => i.json);
const stock = $('Load Inventory').all().map(i => i.json).filter(r => r.SKU).map(r => {
  const counted = r['Counted At'] ? DateTime.fromISO(String(r['Counted At'])) : null;
  const delta = moves.filter(m => m.sku === String(r.SKU) && (!counted || !counted.isValid || DateTime.fromISO(String(m.created_at)) > counted)).reduce((s, m) => s + Number(m.qty || 0), 0);
  return { sku: String(r.SKU), name: r.Name, current: Number(r['Start Stock'] || 0) + delta, threshold: Number(r['Low Stock At'] || 0) };
});
const low = stock.filter(x => x.current <= x.threshold).sort((a, b) => a.current - b.current);
const money = v => Number(v).toLocaleString('id-ID') + ' ' + cur;
return [{ json: {
  date: today.toFormat('d LLL yyyy'), orders: orders.length, revenue, revenue_text: money(revenue), aov_text: orders.length ? money(Math.round(revenue / orders.length)) : '-',
  by_channel: Object.entries(byChannel).map(([channel, v]) => ({ channel, ...v, revenue_text: money(v.revenue) })),
  best, best_text: best[0] ? best[0].name + ' (' + best[0].qty + ')' : '-',
  low, low_text: low.length ? low.slice(0, 5).map(x => x.sku + ': ' + x.current).join(', ') + (low.length > 5 ? ' +' + (low.length - 5) : '') : 'none',
} }];

